import { defineStore } from 'pinia'
import { computed, ref } from 'vue'

export interface CartItem {
  id: string
  name: string
  price: number
  quantity: number
}

export const useCartStore = defineStore('cart', () => {
  const items = ref<CartItem[]>([])

  function add(item: Omit<CartItem, 'quantity'>, quantity = 1) {
    const existing = items.value.find((i) => i.id === item.id)
    if (existing) {
      existing.quantity += quantity
    } else {
      items.value.push({ ...item, quantity })
    }
  }

  function remove(id: string, quantity?: number) {
    const existing = items.value.find((i) => i.id === id)
    if (!existing) return

    if (quantity === undefined || existing.quantity <= quantity) {
      items.value = items.value.filter((i) => i.id !== id)
    } else {
      existing.quantity -= quantity
    }
  }

  const total = computed(() =>
    items.value.reduce((sum, item) => sum + item.price * item.quantity, 0)
  )

  return { items, add, remove, total }
})
```

- `add` takes an item without `quantity` (defaults to 1) and merges into an existing line if the id already exists.
- `remove` removes the whole line by default, or decrements by a given quantity if passed.
- `total` is a computed getter summing `price * quantity` across all items.
